/// Read-only Mushaf data (generated by tool/build_quran_assets.py; format in
/// specs/001-mushaf-reader-wirds/contracts/assets.md).
library;

class SurahInfo {
  const SurahInfo({
    required this.number,
    required this.name,
    required this.ayahs,
    required this.startPage,
  });

  factory SurahInfo.fromJson(Map<String, dynamic> json) => SurahInfo(
        number: json['n'] as int,
        name: json['name'] as String,
        ayahs: json['ayahs'] as int,
        startPage: json['startPage'] as int,
      );

  final int number;
  final String name;
  final int ayahs;

  /// Page of the surah's first ayah (matches the printed index).
  final int startPage;
}

class MushafWord {
  const MushafWord({
    required this.id,
    required this.key,
    required this.glyph,
    required this.surah,
    required this.ayah,
  });

  factory MushafWord.fromJson(Map<String, dynamic> json) {
    final key = json['k'] as String;
    final parts = key.split(':');
    return MushafWord(
      id: json['id'] as int,
      key: key,
      glyph: json['g'] as String,
      surah: int.parse(parts[0]),
      ayah: int.parse(parts[1]),
    );
  }

  /// 1..83,668, unique and in Mushaf order.
  final int id;

  /// "surah:ayah:word", e.g. "1:1:1".
  final String key;
  final String glyph;
  final int surah;
  final int ayah;
}

enum LineType {
  ayah,
  surahName,
  basmallah;

  static LineType parse(String value) => switch (value) {
        'ayah' => LineType.ayah,
        'surah_name' => LineType.surahName,
        'basmallah' => LineType.basmallah,
        _ => throw FormatException('Unknown line type: $value'),
      };
}

class MushafLine {
  const MushafLine({
    required this.number,
    required this.type,
    required this.centered,
    required this.surah,
    required this.words,
  });

  factory MushafLine.fromJson(Map<String, dynamic> json) => MushafLine(
        number: json['n'] as int,
        type: LineType.parse(json['type'] as String),
        centered: json['centered'] as bool,
        surah: json['surah'] as int?,
        words: [
          for (final w in json['words'] as List<dynamic>)
            MushafWord.fromJson(w as Map<String, dynamic>),
        ],
      );

  final int number;
  final LineType type;
  final bool centered;

  /// Set only on [LineType.surahName] lines.
  final int? surah;

  /// Empty unless [type] is [LineType.ayah].
  final List<MushafWord> words;
}

class PageData {
  const PageData({
    required this.page,
    required this.juz,
    required this.hizbQuarter,
    required this.lines,
    this.endMarkerIds = const {},
  });

  factory PageData.fromJson(Map<String, dynamic> json) => PageData(
        page: json['page'] as int,
        juz: json['juz'] as int,
        hizbQuarter: json['hizbQuarter'] as int,
        lines: [
          for (final l in json['lines'] as List<dynamic>)
            MushafLine.fromJson(l as Map<String, dynamic>),
        ],
      );

  final int page;
  final int juz;

  /// 1..240 over the whole Mushaf.
  final int hizbQuarter;
  final List<MushafLine> lines;

  /// The ids of the words of this page that are the end marker of their ayah (the last word of the ayah). Derived
  /// by `MushafRepository.loadPage`, never stored; a look that colours the markers uses it, and it changes nothing
  /// about the text or the layout. Empty when the page was not loaded through the repository.
  final Set<int> endMarkerIds;

  /// The same page with [ids] as its end markers.
  PageData withEndMarkers(Set<int> ids) => PageData(
        page: page,
        juz: juz,
        hizbQuarter: hizbQuarter,
        lines: lines,
        endMarkerIds: ids,
      );
}

class MushafMeta {
  MushafMeta({
    required this.surahs,
    required this._pageJuz,
    required this._pageHizbQuarter,
    required this._pageSurahs,
    required this._ayahPage,
  });

  factory MushafMeta.fromJson(Map<String, dynamic> json) => MushafMeta(
        surahs: [
          for (final s in json['surahs'] as List<dynamic>)
            SurahInfo.fromJson(s as Map<String, dynamic>),
        ],
        pageJuz: (json['pageJuz'] as List<dynamic>).cast<int>(),
        pageHizbQuarter: (json['pageHizbQuarter'] as List<dynamic>).cast<int>(),
        pageSurahs: [
          for (final l in json['pageSurahs'] as List<dynamic>) (l as List<dynamic>).cast<int>(),
        ],
        ayahPage: (json['ayahPage'] as Map<String, dynamic>).cast<String, int>(),
      );

  static const int pageCount = 604;
  static const int surahCount = 114;

  final List<SurahInfo> surahs;
  final List<int> _pageJuz;
  final List<int> _pageHizbQuarter;
  final List<List<int>> _pageSurahs;
  final Map<String, int> _ayahPage;

  int _checked(int page) {
    if (page < 1 || page > pageCount) throw RangeError.range(page, 1, pageCount, 'page');
    return page - 1;
  }

  int juzOf(int page) => _pageJuz[_checked(page)];

  /// 1..240.
  int hizbQuarterOf(int page) => _pageHizbQuarter[_checked(page)];

  /// Surahs that have a title line or a word on [page].
  List<int> surahsOn(int page) => _pageSurahs[_checked(page)];

  int pageOfAyah(int surah, int ayah) {
    final page = _ayahPage['$surah:$ayah'];
    if (page == null) throw RangeError('No such ayah $surah:$ayah');
    return page;
  }

  SurahInfo surah(int number) {
    if (number < 1 || number > surahs.length) throw RangeError.range(number, 1, surahs.length, 'surah');
    return surahs[number - 1];
  }
}
